"""Independent three-valued reference for this fixed VALUES corpus.

This does not replace or change the captured Spark reference. It checks SQL
NULL rules separately, with Spark's existing DOUBLE coercion and NaN equality.
"""
import hashlib
import json
import math
import runpy
import struct
from decimal import Decimal
from pathlib import Path

p = Path(__file__).parent
before = hashlib.sha256((p / 'cases.jsonl').read_bytes()).hexdigest()
c = runpy.run_path(str(p / 'corpus.py'))
assert before == hashlib.sha256((p / 'cases.jsonl').read_bytes()).hexdigest()


def value(raw, ty):
    if raw is None:
        return None
    if ty == 'BIGINT':
        return int(Decimal(raw))
    if ty == 'FLOAT':
        return struct.unpack('!f', struct.pack('!f', float(raw)))[0]
    return float(raw) if ty == 'DOUBLE' else Decimal(raw)


def equal(left, right):
    if left is None or right is None:
        return None
    if isinstance(left, float) or isinstance(right, float):
        left, right = float(left), float(right)
        if math.isnan(left) and math.isnan(right):
            return True
    return left == right


def sql_in(left, right):
    comparisons = [equal(left, r) for r in right]
    return True if True in comparisons else None if None in comparisons else False


def negate(x):
    return None if x is None else not x


def sql_or(x, y):
    return True if x is True or y is True else None if x is None or y is None else False


def sql_and(x, y):
    return False if x is False or y is False else None if x is None or y is None else True


assert sql_in(3, [1, 2, None]) is None
assert sql_in(3, [1, 3, None]) is True
assert sql_in(None, []) is False
assert negate(sql_in(3, [1, 2, None])) is None


def relations(left_type, right_type, shape):
    left = list(c['outer'])
    if left_type in ['FLOAT', 'DOUBLE']:
        left += [(11, 1, 'NaN'), (12, 1, 'Infinity'), (13, 1, '-Infinity')]
    right = list(c['inner'])
    if shape == 'nonnull':
        right = [r for r in right if r[1] is not None]
    if shape == 'allnull':
        right = [(1, None), (1, None), (2, None), (None, None)]
    if right_type in ['FLOAT', 'DOUBLE'] and shape in ['full', 'nonnull']:
        right += [(1, 'NaN'), (1, 'Infinity'), (1, '-Infinity')]
    if shape == 'empty':
        right = []
    return ([(i, g, value(v, left_type)) for i, g, v in left],
            [(g, value(v, right_type)) for g, v in right])


expected = {}
for name, left_type, right_type in c['pairs']:
    for shape in (['full', 'empty', 'allnull', 'nonnull'] if name in ['int', 'double_decimal'] else ['full']):
        left, right = relations(left_type, right_type, shape)
        for correlated in [False, True]:
            for op in ['in', 'not_in', 'exists', 'not_exists']:
                rows = []
                for i, group, v in left:
                    rhs = [r for g, r in right if not correlated or equal(g, group) is True]
                    result = sql_in(v, rhs) if op in ['in', 'not_in'] else any(equal(v, r) is True for r in rhs)
                    rows.append([i, negate(result) if op.startswith('not_') else result])
                expected[f'{name}_{shape}_{int(correlated)}_{op}'] = rows

left, right = relations('DOUBLE', 'DECIMAL(38,18)', 'full')
for correlated in [False, True]:
    names = ['not', 'isnull', 'false', 'coalesce', 'case', 'two_in', 'mixed', 'nested']
    for name in names:
        expected[f'context_{int(correlated)}_{name}'] = []
    expected[f'filter_control_{int(correlated)}'] = []
    for i, group, v in left:
        rhs = [r for g, r in right if not correlated or equal(g, group) is True]
        result = sql_in(v, rhs)
        exists = any(equal(v, r) is True for r in rhs)
        values = [negate(result), result is None, result is False,
                  True if result is None else result,
                  7 if result is True else 9 if result is None else 11,
                  sql_or(result, sql_in(v, [r for g, r in right if g == 2])),
                  sql_and(result, exists), sql_in(v, [r for g, r in right if g is not None])]
        for name, x in zip(names, values, strict=True):
            expected[f'context_{int(correlated)}_{name}'].append([i, x])
        if result is True:
            expected[f'filter_control_{int(correlated)}'].append([i])

# These are the six upstream SQLLogicTest expected results, with booleans
# converted to integers exactly as in this corpus's outer capture wrapper.
upstream = [[[0, 1]], [[0]], [[1, None, None, None]], [[1, 1]],
            [[1, 1], [2, 0], [3, None], [4, 0]],
            [[1, 0], [2, 1], [3, None], [4, 1], [5, None]]]
expected.update({f'upstream_{i}': rows for i, rows in enumerate(upstream, 1)})
for ty in ['FLOAT', 'DOUBLE']:
    left = [value(raw, ty) for raw in ['0.1', 'NaN', '2.5', None]]
    right = [Decimal('0.1'), Decimal('2.5'), None]
    expected[f'{ty.lower()}_correlated_exists'] = [[i, any(equal(v, r) is True for r in right)] for i, v in enumerate(left, 1)]
    expected[f'boundary_{ty.lower()}_in_subquery'] = [[i, sql_in(v, right)] for i, v in enumerate(left, 1)]
for case in c['cases']:
    if '_batch' in case['id']:
        expected[case['id']] = expected[case['id'].rsplit('_batch', 1)[0]]
assert expected.keys() == {x['id'] for x in c['cases']}
expected = {name: [[None if x is None else str(int(x)) for x in row] for row in rows] for name, rows in expected.items()}
captures = {variant: {r['id']: r['actual'] for r in json.loads((p / f'{variant}.json').read_text())['results']} for variant in ['spark', 'after']}
checks = []
for name, rows in expected.items():
    for ansi in ['true', 'false']:
        identifier = f'{name}_{ansi}'
        checks.append({'id': identifier, 'expected_rows': rows,
                       'spark_agrees': captures['spark'][identifier]['rows'] == rows,
                       'after_agrees': captures['after'][identifier]['rows'] == rows,
                       'spark_rows': captures['spark'][identifier]['rows'],
                       'after_rows': captures['after'][identifier]['rows']})
report = {'scope': 'SQL three-valued NULL semantics; Spark numeric coercion and NaN/signed-zero equality; independent of raw Spark agreement',
          'total': len(checks), 'spark_agreement': sum(x['spark_agrees'] for x in checks),
          'after_agreement': sum(x['after_agrees'] for x in checks), 'cases': checks}
(p / 'semantics-check.json').write_text(json.dumps(report, indent=2) + '\n')
print({key: value for key, value in report.items() if key != 'cases'})
print('Candidate differences:', [x['id'] for x in checks if not x['after_agrees']])
for check in checks:
    if not check['after_agrees']:
        # Keep the pre-existing pure floating signed-zero gap explicit. Any
        # other failing row, or a failure outside these cases, fails the check.
        assert check['id'].startswith('float_double_full_'), check['id']
        different = [(x, y) for x, y in zip(check['expected_rows'], check['after_rows'], strict=True) if x != y]
        assert len(different) == 1 and different[0][0][0] == '7', check['id']
